def _dgh_col_kill(m, s, t, cols):
    """Davies-Gill-Horsley (v = s-1) on column sums c_j of an m-row K_{s,t}-free matrix, all k in
    [s, m].  With D = k-s+1, R = (t-1)(m-s+1), a = R mod D, c = R div D the profile is impossible when
    (D-a)*sum_j C(c_j,s-1) > (D-a)*c*C(m,s-1) + sum_j max(k-c_j,0)*C(c_j,s-1)
    (mirror of ZarPrune.argDGHCol; literature review P8 / DGH Lemma 3.2 with v = s-1)."""
    if s < 1:
        return False
    v = s - 1
    R = (t - 1) * (m - s + 1)
    ch = [comb(c, v) for c in cols]
    S = sum(ch)
    Cm = comb(m, v)
    for k in range(s, m + 1):
        D = k - s + 1
        a, c = R % D, R // D
        if (D - a) * S > (D - a) * c * Cm + sum((k - cj) * chj for cj, chj in zip(cols, ch) if cj < k):
            return True
    return False


def _dgh_kill(m, n, s, t, w, rows, cols):
    """Both orientations: the column sums of (m,n;s,t) and of the transpose (n,m;t,s) = the row sums."""
    return _dgh_col_kill(m, s, t, cols) or _dgh_col_kill(n, t, s, rows)


def kill(m, n, s, t, w, rows, cols):
    """Python mirror of candidate.kill (library part mirrors ZarPrune.counting)."""
    if sum(comb(c, s) for c in cols) > (t - 1) * comb(m, s):
        return True                                                   # argA
    if sum(comb(r, t) for r in rows) > (s - 1) * comb(n, t):
        return True                                                   # argAT
    r0, c0 = rows[0], cols[0]
    if r0 and sum(comb(c - 1, s - 1) for c in sorted(cols)[:r0] if c) > (t - 1) * comb(m - 1, s - 1):
        return True                                                   # argD
    if c0 and sum(comb(r - 1, t - 1) for r in sorted(rows)[:c0] if r) > (s - 1) * comb(n - 1, t - 1):
        return True                                                   # argDT
    return _dgh_kill(m, n, s, t, w, rows, cols) or any(r >= 7 for r in rows)
